chmod +x /tmp/askpass.sh; cd /home/runner/work/beetle-in-the-anthill/chandler-conv && GIT_ASKPASS=/tmp/askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/chandler 2>&1 | tail -3
